import {supportsZeroOrigin,boundaryCurve} from './curve-boundary.js?v=2.5.15';
import {lossGroups,resolveComponentCurve} from './loss-models.js?v=2.5.15';
import {QUANTITIES,characteristicName} from './characteristics.js?v=2.5.15';
import {outputPower,sliceWaveform,spectrum,average,rmsTime} from './engine.js?v=2.5.15';
const finite=Number.isFinite,positive=v=>finite(v)&&v>0;
export const characteristicTitle=c=>c?.sourceId?characteristicName(c.sourceId).split(' — ')[0]:`${QUANTITIES[c?.yName]?.[0]||c?.yName} vs ${QUANTITIES[c?.xName]?.[0]||c?.xName}`;
export function lookupQuantity(c){const axes=[c.xName,c.yName];for(const q of ['Id','If','di_dt','Tj'])if(axes.includes(q))return q;if(axes.includes('ESR'))return axes.includes('T')?'T':'f';return axes.includes('B')?'B':axes.includes('f')?'f':c.xName;}
export function checkCharacteristic(c,{given=lookupQuantity(c),policy='error',method='reference-first'}={}){
 const issues=[],add=(code,message,extra={})=>issues.push({code,message,severity:'error',curveId:c.id,...extra});
 if(c.constant!==undefined){if(!finite(c.constant)||c.constant<0)add('constant','Enter a resistance of zero or more ohms.',{field:'curveConstant'});return issues;}
 if(!Array.isArray(c.iterations)||!c.iterations.length){add('iterations','Add at least one curve iteration with two numeric points.');return issues;}
 const keys=[...new Set(c.iterations.flatMap(it=>Object.keys(it.deps||{})))];
 c.iterations.forEach((it,j)=>{const context={iteration:j,field:'points'+j};if(!Array.isArray(it.x)||!Array.isArray(it.y)||it.x.length!==it.y.length||it.x.length===0){add('points','Enter at least two X/Y pairs, one pair per line.',context);return;}
  if(it.x.length===1)add('single-point','This characteristic has one point and will be treated as a constant. Add more points if it should vary.',{...context,severity:'warning'});const bad=it.x.map((x,k)=>!finite(x)||!finite(it.y[k])?k+1:null).filter(Boolean);if(bad.length){add('numeric','Use two finite numbers on each line. Check rows '+bad.join(', ')+'.',{...context,rows:bad});return;}
  // A recorded characteristic must be a function of its stored X axis.
  // Query-First/IDW invert each reference, so their Y axes must also be unique.
  // Curve-First validates inversion only after constructing the combined family.
  // Curve-First reconstructs the stored forward family before inversion,
  // so checking only the requested inverse axis misses malformed X samples.
  const inverse=given===c.yName,referenceInverse=inverse&&method!=='forward-first',axesToCheck=referenceInverse?['x','y']:['x'];
  for(const axis of axesToCheck){
   const values=it[axis],quantity=axis==='x'?c.xName:c.yName,locations=new Map();
   values.forEach((v,k)=>locations.set(v,[...(locations.get(v)||[]),k+1]));
   for(const [value,rows] of locations)if(rows.length>1){
    const outputs=rows.map(row=>it[axis==='x'?'y':'x'][row-1]),identical=outputs.every(v=>v===outputs[0]);
    const currentAxis=['Id','If'].includes(quantity),zeroRule=value===0&&(axis==='x'||currentAxis)&&c.originPolicy==='zero'&&supportsZeroOrigin(c);
    if(zeroRule)continue;
    const guidance=identical?'These identical pairs are redundant; keep one copy.':axis==='x'?'The stored forward characteristic must have one output for each X value.':`The engine looks up ${given} → ${c.xName}: this flat forward segment gives more than one output for the same engine input. ${value===0&&supportsZeroOrigin(c)?'Select the explicit zero-current (0, 0) rule, or edit the branch.':'Select a single-valued branch.'}`;
    add('duplicate',`${QUANTITIES[quantity]?.[0]||quantity} = ${value} ${QUANTITIES[quantity]?.[1]||''} is repeated on rows ${rows.join(', ')}. ${guidance}`,{...context,rows,value,axis,severity:identical?'warning':'error'});
   }
  }
  if(referenceInverse&&policy!=='matlab'){const effective=boundaryCurve(c).iterations[j],ordered=effective.x.map((v,k)=>({x:v,y:effective.y[k]})).sort((a,b)=>a.x-b.x),deltas=ordered.slice(1).map((v,k)=>v.y-ordered[k].y);if(deltas.some(v=>v>0)&&deltas.some(v=>v<0))add('inverse','This inverse lookup turns back on itself. Keep one steadily increasing or decreasing branch.',context);}
  const outputAxis=given===c.yName?'x':'y',outputName=given===c.yName?c.xName:c.yName;if(!['T','Tj','Vgs'].includes(outputName)&&it[outputAxis].some(v=>v<0))add('negative',`The ${QUANTITIES[outputName]?.[0]||outputName} values include a negative magnitude. Check the curve sign and units.`,{...context,rows:it[outputAxis].map((v,k)=>v<0?k+1:null).filter(Boolean)});
  for(const key of keys)if(!finite(it.deps?.[key]))add('dependency',`Enter ${QUANTITIES[key]?.[0]||key} for iteration ${j+1}.`,{iteration:j,dependency:key,field:'dependency:'+key});
 });
 if(c.temperatureIndependent&&new Set(c.iterations.map(it=>it.deps?.Tj)).size>1)add('temperature-independent','Temperature-independent switching energy needs one reference temperature. Keep one temperature slice or enable temperature dependence.');
 const ignored=Object.entries(c.dependencyPolicy||{}).filter(([,v])=>v?.enabled===false);if(ignored.some(([,v])=>!finite(v.reference)))add('reference','Choose a recorded numeric reference for each ignored dependency.');else if(ignored.length&&!c.iterations.some(it=>ignored.every(([key,v])=>it.deps?.[key]===v.reference)))add('reference-combination','The chosen reference conditions do not occur together. Select a combination recorded in the same iteration.');
 if(method!=='inverse-distance'&&keys.filter(k=>new Set(c.iterations.map(it=>it.deps?.[k])).size>1&&!ignored.some(([key])=>key===k)&&!(c.temperatureIndependent&&k==='Tj')).length>3)add('dimensions','This interpolation method supports up to three varying reference conditions. Simplify the family or choose weighted interpolation.');
 return issues;
}
const waveCache=new WeakMap(),powerCache=new WeakMap();
function inspectWave(w){if(waveCache.has(w))return waveCache.get(w);const issues=[],t=w.columns?.[w.time],stats={};if(!Array.isArray(t)||t.length<2)issues.push('Choose a time column with at least two samples.');else if(t.length>200000)issues.push('This file exceeds 200,000 samples. Reduce or split it.');else{for(let j=0;j<t.length;j++)if(!finite(t[j])||(j&&t[j]<=t[j-1])){issues.push('Time must contain finite numbers in strictly increasing order; check row '+(j+1)+'.');break;}}
 for(const [name,a] of Object.entries(w.columns||{})){if(!Array.isArray(a)||a.length!==t?.length){issues.push(name+': the number of samples does not match time.');continue;}let lo=Infinity,hi=-Infinity,integral=0,bad=false;for(let j=0;j<a.length;j++){if(!finite(a[j])){issues.push(name+': replace the missing or nonnumeric value at row '+(j+1)+'.');bad=true;break;}lo=Math.min(lo,a[j]);hi=Math.max(hi,a[j]);if(j&&t)integral+=(t[j]-t[j-1])*(a[j]+a[j-1])/2;}if(!bad)stats[name]={min:lo,max:hi,absMax:Math.max(Math.abs(lo),Math.abs(hi)),mean:t?.length>1?integral/(t.at(-1)-t[0]):0};}
 const data={issues,stats};waveCache.set(w,data);return data;}
function checkedPower(w,op){let cache=powerCache.get(w);if(!cache){cache=new Map();powerCache.set(w,cache);}const key=JSON.stringify([op.outputPairs,op.balancedOutput,op.window]);if(!cache.has(key)){const names=[...new Set([w.time,...(op.outputPairs||[]).flatMap(p=>[p.v,p.i])])].filter(k=>w.columns?.[k]);const selected=sliceWaveform({...w,columns:Object.fromEntries(names.map(k=>[k,w.columns[k]]))},op);cache.set(key,outputPower(selected,op));}return cache.get(key);}
const signalCache=new WeakMap();
function signalCheck(w,signal,op,spectral=false){let cache=signalCache.get(w);if(!cache){cache=new Map();signalCache.set(w,cache);}const key=JSON.stringify([signal,op.window,spectral?op.fftSize:0]);if(!cache.has(key)){const selected=sliceWaveform({...w,columns:{[w.time]:w.columns[w.time],[signal]:w.columns[signal]}},op),t=selected.columns[w.time],values=selected.columns[signal],data={mean:average(t,values),rms:rmsTime(t,values)};if(spectral){const spec=spectrum(t,values,Number(op.fftSize)||1024);data.dc=spec[0].i2;data.total=spec.reduce((sum,h)=>sum+h.i2,0);}cache.set(key,data);}return cache.get(key);}
export function checkProject(project){
 const issues=[],waves=project.waveforms||[],instances=project.instances||[],op=project.operating||{};const add=(category,message,target={},severity='error',details='')=>issues.push({id:'check-'+issues.length,category,message,severity,details,page:'overview',...target});
 if(!instances.length)add('Components','Add a component to this study.',{page:'devices'});if(!waves.length)add('Waveforms','Import your simulation waveforms.',{page:'waveforms'});
 if(!positive(op.window))add('Analysis settings','Enter an analysis window greater than zero seconds.',{field:'op.window'});
 if(!['reference-first','forward-first','inverse-distance',undefined].includes(op.interpolationMethod))add('Analysis settings','Choose one of the supported interpolation methods.',{field:'op.interpolationMethod'});
 if(!['error','clamp','extrapolate',undefined].includes(op.domainPolicy))add('Analysis settings','Choose a supported out-of-domain policy.',{field:'op.domainPolicy'});
 if(![256,512,1024,2048,4096].includes(Number(op.fftSize||1024)))add('Analysis settings','Choose a supported spectral sample count.',{field:'op.fftSize'});
 const signature=c=>[...(c.enabled||[])].sort().join(',');let combinations=instances.length?1:0;const ids=new Set();
 const waveInfo=new Map(waves.map(w=>[w,inspectWave(w)]));for(const w of waves)for(const msg of waveInfo.get(w).issues)add('Waveforms',w.name+': '+msg,{page:'waveforms',waveformId:w.id});
 const pairs=(op.outputPairs||[]).filter(p=>p.v&&p.i);if(!pairs.length)add('Output power','Select an output voltage and current pair.',{field:'op.outputPairs'});else if(op.balancedOutput&&pairs.length!==1)add('Output power','Use one phase pair with balanced ×3, or turn off ×3 and map every phase.',{field:'op.balancedOutput'});
 if(pairs.length&&positive(op.window)&&(!op.balancedOutput||pairs.length===1))for(const w of waves){if(waveInfo.get(w).issues.length)continue;try{const power=checkedPower(w,op);if(power<0)add('Output power',w.name+': output power is negative. Check the mapped signals and polarity.',{field:'op.outputPairs',waveformId:w.id});else if(power===0)add('Output power',w.name+': output power is zero; efficiency cannot be calculated.',{field:'op.outputPairs',waveformId:w.id});}catch(error){add('Output power',w.name+': check output signal mapping.',{field:'op.outputPairs',waveformId:w.id},'error',error.message);}}
 for(const inst of instances){const candidates=inst.candidates||[],base={page:'devices',instanceId:inst.id,device:inst.name,subtab:'settings'};if(ids.has(inst.id))add('Components','Component identifiers are duplicated. Reimport a valid project.',base);ids.add(inst.id);if(!candidates.length)add('Components',inst.name+': add an alternative.',base);combinations*=candidates.length;
  if(candidates.some(c=>signature(c)!==signature(candidates[0])))add('Comparison',inst.name+': use the same enabled loss contributions for every alternative.',base);
  for(const key of ['current','voltage',...(inst.type==='MOSFET'?['gate']:[])]){const signal=inst.mapping?.[key],missing=waves.filter(w=>!signal||!Array.isArray(w.columns?.[signal]));if(!signal||missing.length)add('Signal mapping',`Choose a ${key} signal available in every operating-point file.`,{...base,field:'inst.mapping.'+key},'error',missing.map(w=>w.name).join(', '));}
  for(const c of candidates){const target={...base,candidateId:c.id},context={device:inst.name,part:c.part||'Unnamed alternative'};const push=(category,message,extra={},severity='error',details='')=>add(category,message,{...target,...context,...extra},severity,details);if(ids.has(c.id))push('Components','Alternative identifiers are duplicated. Reimport a valid project.');ids.add(c.id);
   for(const [key,label] of [['series','Devices in series'],['parallel','Devices in parallel'],['totalCount','Total physical device count']])if(!positive(c[key])||!Number.isInteger(c[key]))push('Device settings','Enter a positive whole number for '+label.toLowerCase()+'.',{field:'cand.'+key});
   if(positive(c.series)&&positive(c.parallel)&&positive(c.totalCount)&&c.totalCount!==c.series*c.parallel&&!c.replicationConfirmed)push('Device settings','Confirm the additional replicated banks, or correct the total device count.',{field:'cand.replicationConfirmed'});
   if(!['fixed','iterative'].includes(c.thermal?.mode))push('Thermal settings','Choose a fixed or iterative temperature model.',{subtab:'thermal',field:'cand.thermal.mode'});if(!finite(c.thermal?.temperature))push('Thermal settings','Enter the device or reference temperature.',{subtab:'thermal',field:'cand.thermal.temperature'});
   if(c.thermal?.mode==='iterative'){if(!finite(c.thermal.Rth)||c.thermal.Rth<0)push('Thermal settings','Enter a thermal resistance of zero or more K/W.',{subtab:'thermal',field:'cand.thermal.Rth'});if(!positive(c.thermal.maxTemperature)||c.thermal.maxTemperature<=c.thermal.temperature)push('Thermal settings','Set a temperature limit above the reference temperature.',{subtab:'thermal',field:'cand.thermal.maxTemperature'});}
   if(inst.type==='MOSFET'){if(!['logic','analog'].includes(c.gateType))push('Gate settings','Choose a logic or analog gate waveform.',{field:'cand.gateType'});for(const key of c.gateType==='analog'?['gateOn','gateOff']:['vgsOn','vgsOff'])if(!finite(c[key]))push('Gate settings','Enter '+({gateOn:'the ON threshold',gateOff:'the OFF threshold',vgsOn:'the gate-on voltage',vgsOff:'the gate-off voltage'}[key])+'.',{field:'cand.'+key});if(c.gateType==='analog'&&finite(c.gateOn)&&finite(c.gateOff)&&c.gateOn<=c.gateOff)push('Gate settings','The ON threshold must be above the OFF threshold.',{field:'cand.gateOn'});for(const [category,key] of [['on','rgOn'],['off','rgOff']])if(c.enabled?.includes(category)&&(!finite(c[key])||c[key]<0))push('Gate settings','Enter a nonnegative '+(category==='on'?'turn-on':'turn-off')+' gate resistance.',{field:'cand.'+key});}
   const groups=lossGroups(inst.type),active=new Map();for(const [group,g] of Object.entries(groups)){if(group==='temperature'||!c.enabled?.includes(g.category))continue;try{const cr=resolveComponentCurve(c,group,inst.type);if(!cr){push('Characteristics','Add a characteristic for '+g.title.toLowerCase()+'.',{subtab:'curves',group});continue;}active.set(group,cr);for(const issue of checkCharacteristic(cr,{policy:op.domainPolicy||'error',method:op.interpolationMethod||'reference-first'}))push('Characteristics',issue.message,{subtab:'curves',group,curveId:cr.id,iteration:issue.iteration,rows:issue.rows,code:issue.code},issue.severity);const keys=[...new Set((cr.iterations||[]).flatMap(it=>Object.keys(it.deps||{})))];const conditions={T:c.thermal?.temperature,Tj:c.thermal?.temperature,Vgs:group==='body'?c.vgsOff:c.vgsOn,Rg:group==='on'?c.rgOn:c.rgOff};for(const key of keys){if(cr.dependencyPolicy?.[key]?.enabled===false||(key==='Tj'&&cr.temperatureIndependent)||(key==='Vds'&&['on','off'].includes(group)))continue;const value=conditions[key];if(!finite(value)||(key==='Vgs'&&c.gateType==='analog'))continue;const refs=cr.iterations.map(it=>it.deps?.[key]).filter(finite);if(refs.length&&(value<Math.min(...refs)||value>Math.max(...refs)))push('Reference coverage','Review the '+(QUANTITIES[key]?.[0]||key).toLowerCase()+' reference conditions.',{subtab:'curves',group,curveId:cr.id},refs.length>1&&op.domainPolicy==='error'?'error':'warning',`Requested ${value}; references ${Math.min(...refs)} to ${Math.max(...refs)}.`);}
    const magnitude=lookupQuantity(cr);if(['Id','If'].includes(magnitude)&&positive(c.parallel)){const ranges=cr.iterations?.flatMap(it=>magnitude===cr.xName?it.x:it.y)||[];if(ranges.length&&ranges.every(finite)){const max=Math.max(...ranges),requests=waves.map(w=>(waveInfo.get(w).stats[inst.mapping?.current]?.absMax||0)/c.parallel);if(requests.some(v=>v>max)&&op.domainPolicy==='error')push('Reference coverage','Current may exceed this characteristic. Review the curve range or choose linear extrapolation.',{subtab:'curves',group,curveId:cr.id},'warning','This is a conservative full-waveform check; the exact gate-state queries are checked during analysis.');}}
   }catch(error){push('Characteristics','Choose one compatible active characteristic for '+g.title.toLowerCase()+'.',{subtab:'curves',group},'error',error.message);}}
   if(inst.type==='MOSFET'&&active.get('channel')&&[active.get('channel').xName,active.get('channel').yName].includes('Rds')){try{const norm=resolveComponentCurve(c,'temperature','MOSFET');if(norm){if(active.get('channel').iterations.some(it=>'Tj' in (it.deps||{})))push('Temperature correction','Temperature is applied twice. Use absolute temperature-dependent resistance or the separate correction, not both.',{subtab:'curves',group:'temperature',curveId:norm.id});for(const issue of checkCharacteristic(norm,{policy:op.domainPolicy||'error'}))push('Characteristics',issue.message,{subtab:'curves',group:'temperature',curveId:norm.id},issue.severity);}}catch(error){push('Temperature correction','Select or disable the temperature-correction characteristic.',{subtab:'curves',group:'temperature'},'error',error.message);}}
   if(c.enabled?.includes('recovery')&&!c.recoveryConfirmed)push('Recovery model','Review and confirm the recovery-energy definition before using this loss.',{subtab:'settings',field:'cand.recoveryConfirmed',group:'recovery'});
   if(inst.type==='Inductor'&&c.enabled?.includes('core')){for(const [key,label] of [['N','number of turns'],['Ae','effective core area'],['Vcore','core volume']])if(!positive(c[key]))push('Core model','Enter a positive '+label+'.',{field:'cand.'+key});if(!c.coreApproxConfirmed)push('Core model','Review and confirm the sinusoidal-equivalent core-loss model.',{field:'cand.coreApproxConfirmed'});if(c.coreFrequency!==null&&c.coreFrequency!==undefined&&(!finite(c.coreFrequency)||c.coreFrequency<0))push('Core model','Use zero for automatic frequency detection, or enter a positive frequency.',{field:'cand.coreFrequency'});}
   const resistance=active.get(inst.type==='Capacitor'?'esr':'copper');if(['Capacitor','Inductor'].includes(inst.type)&&resistance&&resistance.constant===undefined&&positive(op.window))for(const w of waves){if(waveInfo.get(w).issues.length||!w.columns?.[inst.mapping?.current])continue;try{const stats=signalCheck(w,inst.mapping.current,op,true);if(inst.type==='Capacitor'&&stats.total>0&&stats.dc>stats.total*1e-5&&(!finite(c.dcResistance)||c.dcResistance<0))push('Capacitor current','The capacitor current has a DC offset. Check the waveform, or enter a DC equivalent series resistance to include its loss.',{field:'cand.dcResistance'},'error',w.name);if(inst.type==='Inductor'&&stats.dc>=Math.max(1e-15,stats.total*1e-8)&&(!finite(c.dcResistance)||c.dcResistance<0))push('Winding model','Enter the DC winding resistance for this current waveform.',{field:'cand.dcResistance'},'error',w.name);}catch(error){push('Analysis window','Check the selected window and spectral sample count.',{page:'overview',field:'op.window'},'error',error.message);}}
   if(inst.type==='Inductor'&&c.enabled?.includes('core')&&positive(op.window))for(const w of waves){if(waveInfo.get(w).issues.length||!w.columns?.[inst.mapping?.voltage])continue;try{const stats=signalCheck(w,inst.mapping.voltage,op);if(Math.abs(stats.mean)>Math.max(1e-9,stats.rms*.01))push('Core waveform','The inductor voltage is not volt-second balanced in this window. Check the winding voltage or choose a steady-state window.',{field:'inst.mapping.voltage'},'error',w.name);}catch(error){push('Analysis window','The analysis window does not contain a usable time interval.',{page:'overview',field:'op.window'},'error',error.message);}}

  }
 }
 if(combinations>200)add('Study size','Reduce the study to at most 200 alternative combinations.');if(combinations*waves.length>2000)add('Study size','Reduce the study to at most 2,000 combination–operating-point results.');
 return {issues,errors:issues.filter(i=>i.severity==='error'),warnings:issues.filter(i=>i.severity==='warning'),ready:!issues.some(i=>i.severity==='error'),combinations};
}
